-- ============================================================================
-- 008_quran_reference_data.sql
--
-- مصدر الحقيقة القرآني: كل سورة وكل آية بأرقامها الرسمية، مرتبطة برقم صفحتها
-- الفعلي في مصحف المدينة (٦٠٤ صفحة) وجزئها. المصدر: quran.com API الرسمي
-- (مبني على بيانات مجمع الملك فهد لطباعة المصحف الشريف)، بتاريخ التوليد أدناه.
-- هذا الملف هو الأساس الذي تُبنى عليه كل حدود المسارات والأوراد لاحقًا —
-- بدل ما تكون نطاقات القرآن نصًا حرًا، تبقى مرتبطة بمعرّف آية ثابت يمكن
-- التحقق منه وحسابه.
-- ============================================================================

create table if not exists quran_surahs (
  surah_no integer primary key check (surah_no between 1 and 114),
  name_ar text not null,
  name_simple text,
  verses_count integer not null,
  revelation_place text,
  page_start integer not null,
  page_end integer not null
);
alter table quran_surahs enable row level security;
drop policy if exists "quran_surahs read" on quran_surahs;
create policy "quran_surahs read" on quran_surahs for select to authenticated using (true);

create table if not exists quran_ayahs (
  id integer primary key,
  surah_no integer not null references quran_surahs(surah_no),
  ayah_no integer not null,
  page_number integer not null,
  juz_number integer not null,
  unique(surah_no, ayah_no)
);
alter table quran_ayahs enable row level security;
drop policy if exists "quran_ayahs read" on quran_ayahs;
create policy "quran_ayahs read" on quran_ayahs for select to authenticated using (true);
create index if not exists idx_quran_ayahs_surah on quran_ayahs(surah_no, ayah_no);
create index if not exists idx_quran_ayahs_page on quran_ayahs(page_number);

